const aiText = $input.item.json.content[0].text;
const jsonMatch = aiText.match(/\{[\s\S]*\}/);
const cdc = jsonMatch ? JSON.parse(jsonMatch[0]) : {};

return { json: { audit_id: $('01 Get Audit').item.json[0].id, company_id: $('01 Get Audit').item.json[0].company_id, cdc: cdc } };

// Estimate hours per flow
const spec = $input.item.json;
const flows = JSON.parse(spec.flows);

const COMPLEXITY_HOURS = {
  low: parseFloat($env.COMPLEXITY_LOW_HOURS) || 8,
  medium: parseFloat($env.COMPLEXITY_MEDIUM_HOURS) || 24,
  high: parseFloat($env.COMPLEXITY_HIGH_HOURS) || 60
};

let totalHours = 0;
flows.forEach(flow => {
  totalHours += COMPLEXITY_HOURS[flow.complexity] || 24;
});

const buffer = parseFloat($env.DEFAULT_BUFFER_PERCENT) || 20;
const totalWithBuffer = totalHours * (1 + buffer / 100);
const hourlyRate = parseFloat($env.DEFAULT_HOURLY_RATE_CHF) || 150;
const totalCost = totalWithBuffer * hourlyRate;

// ROI calculation
const audit = $('01 Get Audit').item.json[0];
const hoursPerWeek = audit.manual_hours_per_week || 10;
const hourlyCostSaved = 50; // CHF per hour saved
const yearlyTimeSaved = hoursPerWeek * 52;
const yearlyCostSaved = yearlyTimeSaved * hourlyCostSaved;
const paybackMonths = (totalCost / (yearlyCostSaved / 12)).toFixed(1);
const roi = ((yearlyCostSaved / totalCost) * 100).toFixed(1);

return {
  json: {
    spec_id: spec.id,
    company_id: spec.company_id,
    total_hours: totalWithBuffer,
    hourly_rate_chf: hourlyRate,
    total_cost_chf: totalCost,
    buffer_percent: buffer,
    confidence_level: 'medium',
    risks: [],
    time_saved_hours_per_week: hoursPerWeek,
    cost_saved_chf_per_year: yearlyCostSaved,
    payback_months: parseFloat(paybackMonths),
    roi_percent: parseFloat(roi)
  }
};

// Create proposal entry
return {
  json: {
    estimate_id: $input.item.json.id,
    company_id: $input.item.json.company_id,
    proposal_document_url: `https://docs.google.com/document/d/PLACEHOLDER_${$input.item.json.id}`,
    status: 'draft'
  }
};
